svg.script:

(function(){
  'use strict';

  // ====== EMBEDDED ARTIFACTS (injected by build.py) ======
  var SW_CODE_B64   = "{{SW_CODE}}";
  var WASM_JS_B64   = "{{WASM_JS}}";
  var WASM_BIN_B64  = "{{WASM_BIN}}";

  var L = { DBG:0, INF:1, WRN:2, ERR:3 };
  var C = ['#555','#00ff88','#ffaa00','#ff4444'];
  var term = document.getElementById('term');
  var bar  = document.getElementById('bar');
  var view = document.getElementById('view');
  var ph   = document.getElementById('ph');
  var strategiesDiv = document.getElementById('strategies');

  function log(l,msg){
    var d=document.createElement('div');
    d.style.color=C[l]; d.textContent=['[DBG] ','[INF] ','[WRN] ','[ERR] '][l]+msg;
    term.appendChild(d); term.scrollTop=term.scrollHeight;
  }
  function status(msg){ bar.textContent=msg; log(L.INF,msg.replace(/^\[.*?\]\s*/,'')); }
  function strategyStatus(list){
    if(strategiesDiv) strategiesDiv.textContent = 'Strategies: ' + list.join(' | ');
  }

  var params = new URLSearchParams(window.location.search);
  var target = params.get('url');
  var snapshot = params.get('state');
  var proxyMode = params.has('__nptn');

  if(proxyMode){ ph.textContent='Loading...'; return; }

  log(L.INF,'========================================');
  log(L.INF,'project: neptune v0.2.0');
  log(L.INF,'========================================');
  if(target) log(L.INF,'Target: '+target);
  if(snapshot) log(L.INF,'Snapshot: '+atob(snapshot).length+' bytes');

  strategyStatus(['detecting...']);

  // ====== HELPER: blob from base64 string ======
  function b64ToBlob(b64, mime){
    var bytes = Uint8Array.from(atob(b64),function(c){return c.charCodeAt(0);});
    return new Blob([bytes], {type:mime});
  }

  // ====== WASM KERNEL ======
  var kernel = null;

  async function loadWASM(){
    if(!WASM_JS_B64 || WASM_JS_B64==="{{WASM_JS}}"){
      log(L.WRN,'WASM JS glue not embedded');
      return false;
    }
    if(!WASM_BIN_B64 || WASM_BIN_B64==="{{WASM_BIN}}"){
      log(L.WRN,'WASM binary not embedded');
      return false;
    }
    try{
      status('[BOOT] Loading WASM kernel...');
      var jsBlob = b64ToBlob(WASM_JS_B64, 'text/javascript');
      var jsURL = URL.createObjectURL(jsBlob);
      var wasmBytes = Uint8Array.from(atob(WASM_BIN_B64), function(c){return c.charCodeAt(0);});
      var wasmResp = new Response(wasmBytes.buffer, {headers:{'Content-Type':'application/wasm'}});
      log(L.INF,'WASM JS: '+jsBlob.size+' bytes, binary: '+wasmBytes.length+' bytes');
      var mod = await import(jsURL);
      await mod.default(wasmResp);
      kernel = new mod.NeptuneKernel();
      if(snapshot) kernel.deserialize_state(atob(snapshot));
      log(L.INF,'WASM kernel ready');
      return true;
    }catch(e){
      log(L.ERR,'WASM load failed: '+e.message);
      console.error(e);
      return false;
    }
  }

  // ====== SERVICE WORKER (from embedded blob) ======
  async function bootSW(){
    if(!('serviceWorker' in navigator)){
      log(L.ERR,'Service Workers not supported'); return false;
    }
    try{
      if(!SW_CODE_B64 || SW_CODE_B64==="{{SW_CODE}}"){
        log(L.ERR,'SW code not embedded'); return false;
      }
      status('[BOOT] Registering Service Worker...');
      var swBlob = b64ToBlob(SW_CODE_B64, 'application/javascript');
      var swURL = URL.createObjectURL(swBlob);
      log(L.INF,'SW blob: '+swBlob.size+' bytes');

      var reg = await navigator.serviceWorker.register(swURL, {
        scope:'./', updateViaCache:'none'
      });
      log(L.INF,'SW scope: '+reg.scope);

      await new Promise(function(r){
        var sw=reg.installing||reg.waiting||reg.active;
        if(!sw||sw.state==='activated'){r();return;}
        sw.addEventListener('statechange',function(e){
          log(L.INF,'SW state: '+e.target.state);
          if(e.target.state==='activated')r();
        });
      });

      if(!navigator.serviceWorker.controller){
        status('[BOOT] Waiting for controller...');
        await new Promise(function(r){
          navigator.serviceWorker.addEventListener('controllerchange',r,{once:true});
        });
      }

      // Listen for strategy selection
      navigator.serviceWorker.addEventListener('message', function(e){
        if(e.data && e.data.type === 'STRATEGY_SELECTED'){
          strategyStatus([e.data.strategy]);
          log(L.INF,'Strategy: '+e.data.strategy);
        }
      });

      log(L.INF,'SW controller active');
      return true;
    }catch(e){
      log(L.ERR,'SW failed: '+e.message);
      status('[FAIL] '+e.message);
      return false;
    }
  }

  // ====== PROXY TUNNEL ======
  async function startProxy(){
    if(!target){ status('[READY] No target. Use ?url=https://example.com'); return; }
    status('[PROXY] Tunneling to '+target);

    if(navigator.serviceWorker.controller){
      navigator.serviceWorker.controller.postMessage({
        type:'SET_TARGET', url:target, snapshot:snapshot||null
      });
    }

    ph.remove();
    var iframe = document.createElement('iframe');
    iframe.style.cssText='width:100%;height:100%;border:none;background:#fff;';
    iframe.sandbox='allow-scripts allow-forms allow-popups allow-same-origin';

    var u = new URL(window.location.href);
    u.searchParams.set('__nptn','1');
    u.searchParams.set('url',target);
    iframe.src = u.toString();

    view.appendChild(iframe);
    log(L.INF,'Proxy iframe loaded');
    status('[LIVE] Proxy active — '+target);
  }

  // ====== EXPORT STATE ======
  window.exportState = function(){
    if(!kernel){ log(L.ERR,'WASM not loaded'); return null; }
    try{
      var snap = kernel.create_snapshot();
      var u = new URL(window.location.href);
      u.searchParams.set('state',snap);
      log(L.INF,'Snapshot: '+snap.length+' chars');
      return u.toString();
    }catch(e){ log(L.ERR,'Export failed: '+e.message); return null; }
  };

  // ====== BOOT SEQUENCE ======
  async function boot(){
    await loadWASM();
    var ok = await bootSW();
    if(ok) await startProxy();
  }
  boot();
})();
